import React, { useState, useEffect, useContext } from 'react';
import { Context } from "../index";
import { observer } from "mobx-react-lite";
import { Container, Table, Button, Modal, Alert, Card, Spinner, Badge, Row, Col } from 'react-bootstrap';
import { useHistory, useParams } from 'react-router-dom';
import { getUserInfo, getSellerInfo, blockUser, unblockUser } from '../http/userAPI';

const UserDetails = observer(() => {
    const { user } = useContext(Context);
    const history = useHistory();
    const { userId } = useParams(); // Получаем ID пользователя из URL
    
    const [userData, setUserData] = useState(null);
    const [seller, setSeller] = useState(null);
    const [sellerProducts, setSellerProducts] = useState([]);
    const [reviews, setReviews] = useState([]);
    const [showBlockModal, setShowBlockModal] = useState(false);
    const [showUnblockModal, setShowUnblockModal] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [loading, setLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState(false);

    useEffect(() => {
        if (userId) {
            fetchUserDetails();
        }
    }, [userId]);

    const fetchUserDetails = async () => {
        setLoading(true);
        try {
            // Получаем информацию о пользователе
            const userInfo = await getUserInfo(userId);
            setUserData(userInfo);

            // Если пользователь является продавцом, получаем его профиль продавца
            if (userInfo.role === 'SELLER' || userInfo.sellerId) {
                const sellerData = await getSellerInfo(userId);
                setSeller(sellerData);
                
                // Загружаем товары продавца
                if (sellerData.id) {
                    await loadSellerProducts(sellerData.id);
                }

                // Загружаем отзывы о продавце
                await loadSellerReviews(sellerData.id);
            }

            setError('');
        } catch (e) {
            setError('Ошибка при загрузке данных пользователя: ' + (e.response?.data?.message || e.message));
        } finally {
            setLoading(false);
        }
    };

    const loadSellerProducts = async (sellerId) => {
        try {
            const response = await fetch(`http://localhost:5000/api/seller/${sellerId}/products`);
            if (response.ok) {
                const products = await response.json();
                setSellerProducts(products);
            }
        } catch (error) {
            console.error('Ошибка при загрузке товаров:', error);
        }
    };

    const loadSellerReviews = async (sellerId) => {
        try {
            const response = await fetch(`http://localhost:5000/api/seller/${sellerId}/reviews`);
            if (response.ok) {
                const reviewsData = await response.json();
                setReviews(reviewsData);
            }
        } catch (error) {
            console.error('Ошибка при загрузке отзывов:', error);
        }
    };

    const handleBlock = async () => {
        setActionLoading(true);
        try {
            await blockUser(userId);
            setShowBlockModal(false);
            setSuccess('Пользователь успешно заблокирован');
            fetchUserDetails(); // Обновляем данные
        } catch (e) {
            setError('Ошибка при блокировке пользователя: ' + (e.response?.data?.message || e.message));
        } finally {
            setActionLoading(false);
        }
    };

    const handleUnblock = async () => {
        setActionLoading(true);
        try {
            await unblockUser(userId);
            setShowUnblockModal(false);
            setSuccess('Пользователь успешно разблокирован');
            fetchUserDetails(); // Обновляем данные
        } catch (e) {
            setError('Ошибка при разблокировке пользователя: ' + (e.response?.data?.message || e.message));
        } finally {
            setActionLoading(false);
        }
    };

    const openBlockModal = () => {
        setShowBlockModal(true);
        setError('');
        setSuccess('');
    };

    const openUnblockModal = () => {
        setShowUnblockModal(true);
        setError('');
        setSuccess('');
    };

    if (loading) {
        return (
            <Container className="mt-4 d-flex justify-content-center">
                <Spinner animation="border" role="status">
                    <span className="visually-hidden">Загрузка...</span>
                </Spinner>
            </Container>
        );
    }

    if (!userData) {
        return (
            <Container className="mt-4">
                <Alert variant="danger">Пользователь не найден</Alert>
            </Container>
        );
    }

    return (
        <Container className="mt-4">
            <Card className="mb-4">
                <Card.Header className="d-flex justify-content-between align-items-center">
                    <div>
                        <h2 className="mb-0">Детальная информация о пользователе</h2>
                        <p className="text-muted mb-0">ID: {userData.id}</p>
                    </div>
                    <div>
                        {!userData.is_blocked ? (
                            <Button 
                                variant="outline-warning" 
                                onClick={openBlockModal}
                                disabled={actionLoading || 
                                         userData.id === user.user.id || 
                                         userData.role === 'ADMIN'}
                                title={userData.role === 'ADMIN' ? 'Нельзя заблокировать администратора' : 
                                       userData.id === user.user.id ? 'Нельзя заблокировать себя' : ''}
                            >
                                🔒 Блокировать
                            </Button>
                        ) : (
                            <Button 
                                variant="outline-success" 
                                onClick={openUnblockModal}
                                disabled={actionLoading}
                            >
                                🔓 Разблокировать
                            </Button>
                        )}
                    </div>
                </Card.Header>
                <Card.Body>
                    {error && <Alert variant="danger">{error}</Alert>}
                    {success && <Alert variant="success">{success}</Alert>}

                    <Row>
                        <Col md={6}>
                            <h4>Основная информация</h4>
                            <Table striped bordered>
                                <tbody>
                                    <tr>
                                        <td><strong>ID</strong></td>
                                        <td>{userData.id}</td>
                                    </tr>
                                    <tr>
                                        <td><strong>Имя пользователя</strong></td>
                                        <td>{userData.username}</td>
                                    </tr>
                                    <tr>
                                        <td><strong>Email</strong></td>
                                        <td>{userData.email}</td>
                                    </tr>
                                    <tr>
                                        <td><strong>Телефон</strong></td>
                                        <td>{userData.phone || 'Не указан'}</td>
                                    </tr>
                                    <tr>
                                        <td><strong>Роль</strong></td>
                                        <td>
                                            <Badge bg={userData.role === 'ADMIN' ? 'danger' : 
                                                     userData.role === 'SELLER' ? 'warning' : 'primary'}>
                                                {userData.role}
                                            </Badge>
                                        </td>
                                    </tr>
                                    <tr>
                                        <td><strong>Статус</strong></td>
                                        <td>
                                            <Badge bg={userData.is_blocked ? 'danger' : 'success'}>
                                                {userData.is_blocked ? 'Заблокирован' : 'Активен'}
                                            </Badge>
                                        </td>
                                    </tr>
                                    <tr>
                                        <td><strong>Дата регистрации</strong></td>
                                        <td>{new Date(userData.createdAt).toLocaleDateString('ru-RU')}</td>
                                    </tr>
                                </tbody>
                            </Table>
                        </Col>

                        {/* Информация о продавце */}
                        {seller && (
                            <Col md={6}>
                                <h4>Информация о продавце</h4>
                                <Table striped bordered>
                                    <tbody>
                                        <tr>
                                            <td><strong>ID продавца</strong></td>
                                            <td>{seller.id}</td>
                                        </tr>
                                        <tr>
                                            <td><strong>Название магазина</strong></td>
                                            <td>{seller.name}</td>
                                        </tr>
                                        <tr>
                                            <td><strong>Описание</strong></td>
                                            <td>{seller.description || 'Не указано'}</td>
                                        </tr>
                                        <tr>
                                            <td><strong>Рейтинг</strong></td>
                                            <td>
                                                {seller.rating ? (
                                                    <Badge bg="info">{seller.rating.toFixed(1)} ⭐</Badge>
                                                ) : (
                                                    'Нет оценок'
                                                )}
                                            </td>
                                        </tr>
                                        <tr>
                                            <td><strong>Количество товаров</strong></td>
                                            <td>
                                                <Badge bg="secondary">{sellerProducts.length}</Badge>
                                            </td>
                                        </tr>
                                        <tr>
                                            <td><strong>Количество отзывов</strong></td>
                                            <td>
                                                <Badge bg="secondary">{reviews.length}</Badge>
                                            </td>
                                        </tr>
                                    </tbody>
                                </Table>
                            </Col>
                        )}
                    </Row>
                </Card.Body>
            </Card>

            {/* Товары продавца */}
            {seller && sellerProducts.length > 0 && (
                <Card className="mb-4">
                    <Card.Header>
                        <h4 className="mb-0">Товары продавца ({sellerProducts.length})</h4>
                    </Card.Header>
                    <Card.Body>
                        <Row>
                            {sellerProducts.map(product => (
                                <Col md={6} lg={4} key={product.id} className="mb-3">
                                    <Card>
                                        <Card.Img 
                                            variant="top" 
                                            src={product.img} 
                                            style={{ height: '200px', objectFit: 'cover' }}
                                            onError={(e) => {
                                                e.target.src = 'https://via.placeholder.com/300x200?text=No+Image';
                                            }}
                                        />
                                        <Card.Body>
                                            <Card.Title>{product.name}</Card.Title>
                                            <Card.Text>
                                                <strong>Город:</strong> {product.city}<br/>
                                                <strong>Цена:</strong> {product.price_type === 'fixed' && product.price ? 
                                                    `${product.price} ${product.currency || 'BYN'}` : 
                                                    product.price_type === 'negotiable' ? 'Договорная' : 
                                                    product.price_text || 'Цена не указана'}
                                            </Card.Text>
                                            <small className="text-muted">
                                                Создан: {new Date(product.createdAt).toLocaleDateString('ru-RU')}
                                            </small>
                                        </Card.Body>
                                    </Card>
                                </Col>
                            ))}
                        </Row>
                    </Card.Body>
                </Card>
            )}

            {/* Отзывы о продавце */}
            {seller && reviews.length > 0 && (
                <Card className="mb-4">
                    <Card.Header>
                        <h4 className="mb-0">Отзывы о продавце ({reviews.length})</h4>
                    </Card.Header>
                    <Card.Body>
                        {reviews.map(review => (
                            <Card key={review.id} className="mb-3">
                                <Card.Body>
                                    <div className="d-flex justify-content-between align-items-start">
                                        <div>
                                            <h6 className="mb-1">
                                                {review.author?.username || 'Анонимный пользователь'}
                                            </h6>
                                            <div className="mb-2">
                                                {[...Array(5)].map((_, i) => (
                                                    <span key={i} style={{ color: i < review.rating ? '#ffc107' : '#e4e5e9' }}>
                                                        ⭐
                                                    </span>
                                                ))}
                                                <span className="ms-2">
                                                    <Badge bg="warning">{review.rating}.0</Badge>
                                                </span>
                                            </div>
                                            <p className="mb-1">{review.comment}</p>
                                        </div>
                                        <small className="text-muted">
                                            {new Date(review.createdAt).toLocaleDateString('ru-RU')}
                                        </small>
                                    </div>
                                </Card.Body>
                            </Card>
                        ))}
                    </Card.Body>
                </Card>
            )}

            {/* Сообщения, если нет данных */}
            {seller && sellerProducts.length === 0 && (
                <Alert variant="info">У этого продавца пока нет товаров</Alert>
            )}

            {seller && reviews.length === 0 && (
                <Alert variant="info">У этого продавца пока нет отзывов</Alert>
            )}

            {!seller && (
                <Alert variant="info">Этот пользователь не является продавцом</Alert>
            )}

            {/* Модальные окна блокировки/разблокировки */}
            <Modal show={showBlockModal} onHide={() => !actionLoading && setShowBlockModal(false)}>
                <Modal.Header closeButton>
                    <Modal.Title>Подтверждение блокировки</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    Вы уверены, что хотите заблокировать пользователя <strong>{userData?.username}</strong>?
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={() => setShowBlockModal(false)} disabled={actionLoading}>
                        Отмена
                    </Button>
                    <Button variant="warning" onClick={handleBlock} disabled={actionLoading}>
                        {actionLoading ? <Spinner size="sm" /> : 'Заблокировать'}
                    </Button>
                </Modal.Footer>
            </Modal>

            <Modal show={showUnblockModal} onHide={() => !actionLoading && setShowUnblockModal(false)}>
                <Modal.Header closeButton>
                    <Modal.Title>Подтверждение разблокировки</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    Вы уверены, что хотите разблокировать пользователя <strong>{userData?.username}</strong>?
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={() => setShowUnblockModal(false)} disabled={actionLoading}>
                        Отмена
                    </Button>
                    <Button variant="success" onClick={handleUnblock} disabled={actionLoading}>
                        {actionLoading ? <Spinner size="sm" /> : 'Разблокировать'}
                    </Button>
                </Modal.Footer>
            </Modal>
        </Container>
    );
});

export default UserDetails;
